	@Override
	public List<Error> validateCityDetails(CompanyCityMasterSaveReq req) {
		List<Error> errorList = new ArrayList<Error>();

		try {

			if (StringUtils.isBlank(req.getCityName())) {
				errorList.add(new Error("02", "CityName", "Please Select City  Name "));
			} else if (req.getCityName().length() > 100) {
				errorList.add(new Error("02", "CityName", "Please Enter City  Name within 100 Characters"));
			} else if (StringUtils.isBlank(req.getCityId().toString())) {
				Long CityCount = repo.countByCityNameOrderByEntryDateDesc(req.getCityName());
				if (CityCount > 0) {
					errorList.add(new Error("01", "CityName", "This City Name Alrady Exist "));
				}
			}

			if (StringUtils.isBlank(req.getCountryId()) || req.getCountryId() == null) {
				errorList.add(new Error("03", "CountryId", "Please Select Country Id "));
			}

			// Date Validation
			Calendar cal = new GregorianCalendar();
			Date today = new Date();
			cal.setTime(today);
			cal.add(Calendar.DAY_OF_MONTH, -1);
			cal.set(Calendar.HOUR_OF_DAY, 23);
			cal.set(Calendar.MINUTE, 50);
			today = cal.getTime();
			if (req.getEffectiveDateStart() == null) {
				errorList.add(new Error("04", "EffectiveDateStart", "Please Enter Effective Date Start "));

			} else if (req.getEffectiveDateStart().before(today)) {
				errorList
						.add(new Error("04", "EffectiveDateStart", "Please Enter Effective Date Start as Future Date"));
			} else if (req.getEffectiveDateEnd() == null) {
				errorList.add(new Error("04", "EffectiveDateEnd", "Please Enter Effective Date End "));

			} else if (req.getEffectiveDateEnd().before(req.getEffectiveDateStart())
					|| req.getEffectiveDateEnd().equals(req.getEffectiveDateStart())) {
				errorList.add(new Error("04", "EffectiveDateStart",
						"Please Enter Effective Date End  is After Effective Date Start"));
			}
			// Status Validation
			if (StringUtils.isBlank(req.getStatus())) {
				errorList.add(new Error("05", "Status", "Please Enter Status"));
			} else if (req.getStatus().length() > 1) {
				errorList.add(new Error("05", "Status", "Status 1 Character Only"));
			} else if (!("Y".equals(req.getStatus()) || "N".equals(req.getStatus()))) {
				errorList.add(new Error("05", "Status", "Enter Status Y or N Only"));
			}

			if (StringUtils.isBlank(req.getStateId()) || req.getStateId() == null) {
				errorList.add(new Error("06", "StateId", "Please Select State Id "));
			}
			if (StringUtils.isBlank(req.getCreatedBy())) {
				errorList.add(new Error("07", "CreatedBy", "Please Enter CreatedBy"));
			} else if (req.getCreatedBy().length() > 100) {
				errorList.add(new Error("07", "CreatedBy", "Please Enter CreatedBy within 100 Characters"));
			}

			if (StringUtils.isBlank(req.getCoreAppCode())) {
				errorList.add(new Error("08", "CoreAppCode", "Please Enter CoreAppCode"));
			} else if (req.getCoreAppCode().length() > 20) {
				errorList.add(new Error("08", "CoreAppCode", "Please Enter CoreAppCode within 20 Characters"));
			}
			else if (StringUtils.isBlank(req.getCoreAppCode())) {
				List<CompanyCityMaster> coreAppCode = getCoreAppCodeExistDetails(req.getCompanyId() , req.getCountryId() ,req.getRegionId(),req.getStateId(),null);
				if (coreAppCode.size()>0 ) {
					errorList.add(new Error("08", "CoreAppCode", "This core App Code  Already Exist "));
				}
			}else  {
				List<CompanyCityMaster> coreAppCode =  getCoreAppCodeExistDetails(req.getCompanyId(),req.getCountryId() , req.getRegionId(),req.getStateId(),req.getCityId());
				if (coreAppCode.size()>0 &&  (! req.getCityId().equalsIgnoreCase(coreAppCode.get(0).getCityId().toString())) ) {
					errorList.add(new Error("08", "Core App Code", "This core App Code Already Exist "));
				}
			}
			if (StringUtils.isBlank(req.getRegulatoryCode())) {
				errorList.add(new Error("09", "RegulatoryCode", "Please Enter RegulatoryCode"));
			} else if (req.getRegulatoryCode().length() > 20) {
				errorList.add(new Error("09", "RegulatoryCode", "Please Enter RegulatoryCode within 20 Characters"));
			}

			if (StringUtils.isBlank(req.getRemarks())) {
				errorList.add(new Error("10", "Remarks", "Please Enter Remarks"));
			} else if (req.getRemarks().length() > 100) {
				errorList.add(new Error("10", "Remarks", "Please Enter Remarks within 100 Characters"));
			}
		} catch (Exception e) {
			log.error(e);
			e.printStackTrace();
		}
		return errorList;
	}

	public List<CompanyCityMaster> getCoreAppCodeExistDetails(String companyId , String countryId , String regionCode, String stateId, String cityId ) {
		List<CompanyCityMaster> list = new ArrayList<CompanyCityMaster>();
		try {
			// Find Latest Record
			CriteriaBuilder cb = em.getCriteriaBuilder();
			CriteriaQuery<CompanyCityMaster> query = cb.createQuery(CompanyCityMaster.class);
	
			// Find All
			Root<CompanyCityMaster> b = query.from(CompanyCityMaster.class);
	
			// Select
			query.select(b);
	
			// Effective Date Max Filter
			Subquery<Long> effectiveDate = query.subquery(Long.class);
			Root<CompanyCityMaster> ocpm1 = effectiveDate.from(CompanyCityMaster.class);
			effectiveDate.select(cb.max(ocpm1.get("effectiveDateStart")));
			Predicate a1 = cb.equal(ocpm1.get("companyId"), b.get("companyId"));
			Predicate a2 = cb.equal(ocpm1.get("countryId"),b.get("countryId"));
			Predicate a3 = cb.equal(ocpm1.get("regionCode"), b.get("regionCode"));
			Predicate a4 = cb.equal(ocpm1.get("stateId"), b.get("stateId"));
			
			effectiveDate.where(a1,a2,a3,a4);
	
			Predicate n1 = cb.equal(b.get("effectiveDateStart"), effectiveDate);
			Predicate n2 = cb.equal(b.get("companyId"),companyId);	
			Predicate n3 = cb.equal(b.get("countryId"), countryId );
			Predicate n4 = cb.equal(b.get("regionCode"),regionCode);
			Predicate n5 = cb.equal(b.get("stateId"),stateId);
			
			if( StringUtils.isBlank(cityId)) {
				query.where(n1,n2,n3,n4,n5);	
			} else {
				Predicate n6 = cb.equal(b.get("cityId"),cityId);
				query.where(n1,n2,n3,n4,n5,n6);
			}
			
			// Get Result
			TypedQuery<CompanyCityMaster> result = em.createQuery(query);
			list = result.getResultList();		
		
		} catch (Exception e) {
			e.printStackTrace();
			log.info(e.getMessage());
	
		}
		return list;
	}
	
	
	
	@Override
	public SuccessRes insertCity(CompanyCityMasterSaveReq req) {
		SimpleDateFormat sdformat = new SimpleDateFormat("dd/MM/YYYY");
		SuccessRes res = new SuccessRes();
		CompanyCityMaster saveData = new CompanyCityMaster();
		List<CompanyCityMaster> list = new ArrayList<CompanyCityMaster>();
		DozerBeanMapper dozerMapper = new DozerBeanMapper();

		try {
			Integer amendId = 0;
			Calendar cal = new GregorianCalendar();
			cal.setTime(req.getEffectiveDateStart());
			cal.set(Calendar.HOUR_OF_DAY, 23);
			cal.set(Calendar.MINUTE, 59);
			Date startDate = cal.getTime();
			Date today = new Date();
			cal.setTime(req.getEffectiveDateStart());
			cal.set(Calendar.HOUR_OF_DAY, today.getHours());
			cal.set(Calendar.MINUTE, today.getMinutes());
			Date oldEndDate = cal.getTime();
			cal.setTime(req.getEffectiveDateStart());
			cal.set(Calendar.HOUR_OF_DAY, today.getHours());
			cal.set(Calendar.MINUTE, today.getMinutes());
			Date effDate = cal.getTime();
			Date endDate = req.getEffectiveDateEnd();

			String cityId = "";

			if (StringUtils.isBlank(req.getCityId().toString())) {
				// Save
				// Long totalCount = repo.count();
				Long totalCount = getMasterTableCount();
				cityId = Long.valueOf(totalCount + 1).toString();
				res.setResponse("Saved Successfully ");
				res.setSuccessId(cityId);

			} else {
				// Update
				// Get Less than Equal Today Record
				// Criteria
				cityId = req.getCityId();
				CriteriaBuilder cb = em.getCriteriaBuilder();
				CriteriaQuery<CompanyCityMaster> query = cb.createQuery(CompanyCityMaster.class);

				// Find All
				Root<CompanyCityMaster> b = query.from(CompanyCityMaster.class);

				// Select
				query.select(b);

				// Effective Date Max Filter
				Subquery<Long> effectiveDate = query.subquery(Long.class);
				Root<CompanyCityMaster> ocpm1 = effectiveDate.from(CompanyCityMaster.class);
				effectiveDate.select(cb.max(ocpm1.get("effectiveDateStart")));
				Predicate a1 = cb.equal(ocpm1.get("cityId"), b.get("cityId"));
				Predicate a2 = cb.lessThanOrEqualTo(ocpm1.get("effectiveDateStart"), startDate);
				Predicate a3 = cb.equal(ocpm1.get("countryId"), b.get("countryId"));
				Predicate a4 = cb.equal(ocpm1.get("regionId"), b.get("regionId"));
				Predicate a5 = cb.equal(ocpm1.get("stateId"), b.get("stateId"));
				Predicate a6 = cb.equal(ocpm1.get("companyId"), b.get("companyId"));

				effectiveDate.where(a1, a2, a3, a4, a5, a6);

				// Order By
				// List<Order> orderList = new ArrayList<Order>();
				// orderList.add(cb.asc(b.get("branchName")));

				// Where
				Predicate n1 = cb.equal(b.get("status"), "Y");
				Predicate n2 = cb.equal(b.get("effectiveDateStart"), effectiveDate);
				Predicate n3 = cb.equal(b.get("cityId"), req.getCityId());
				Predicate n4 = cb.equal(b.get("countryId"), req.getCountryId());
				Predicate n5 = cb.equal(b.get("regionId"), req.getRegionId());
				Predicate n6 = cb.equal(b.get("stateId"), req.getStateId());
				Predicate n7 = cb.equal(b.get("companyId"), req.getCompanyId());

				query.where(n1, n2, n3, n4, n5, n6, n7);// .orderBy(orderList);

				// Get Result
				TypedQuery<CompanyCityMaster> result = em.createQuery(query);
				list = result.getResultList();

				if (list.size() > 0) {
					repo.delete(list.get(0));
					// Amend ID
					if (list.get(0).getEffectiveDateStart().before(startDate)) {
						String startDatewithoutTime = sdformat.format(startDate);
						String oldDatewithoutTime = sdformat.format(list.get(0).getEffectiveDateStart());

						if (startDatewithoutTime.equalsIgnoreCase(oldDatewithoutTime)) {
							amendId = list.get(0).getAmendId() + 1;
						}
					}
				}
				res.setResponse("Updated Successfully ");
				res.setSuccessId(cityId);

			}

			dozerMapper.map(req, saveData);
			saveData.setCityId(Integer.valueOf(cityId));
			saveData.setCityName(req.getCityName());
			saveData.setEffectiveDateStart(effDate);
			saveData.setEffectiveDateEnd(endDate);
			saveData.setStatus(req.getStatus());
			saveData.setEntryDate(new Date());
			saveData.setAmendId(amendId);
			repo.saveAndFlush(saveData);

			if (list.size() > 0) {
				// Update Old Record
				CompanyCityMaster lastRecord = list.get(0);
				lastRecord.setEffectiveDateEnd(oldEndDate);
				repo.saveAndFlush(lastRecord);
			}

			log.info("Saved Details is ---> " + json.toJson(saveData));

		} catch (Exception e) {
			e.printStackTrace();
			log.info("Exception is --->" + e.getMessage());
			return null;
		}
		return res;

	}

	public Long getMasterTableCount() {

		Long data = 0L;
		try {

			List<Long> list = new ArrayList<Long>();
			// Find Latest Record
			CriteriaBuilder cb = em.getCriteriaBuilder();
			CriteriaQuery<Long> query = cb.createQuery(Long.class);

			// Find All
			Root<CompanyCityMaster> b = query.from(CompanyCityMaster.class);

			// Select
			query.multiselect(cb.count(b));

			// Effective Date Max Filter
			Subquery<Long> effectiveDate = query.subquery(Long.class);
			Root<CompanyCityMaster> ocpm1 = effectiveDate.from(CompanyCityMaster.class);
			effectiveDate.select(cb.max(ocpm1.get("effectiveDateStart")));
			Predicate a1 = cb.equal(ocpm1.get("cityId"), b.get("cityId"));
			Predicate a2 = cb.equal(ocpm1.get("companyId"), b.get("companyId"));

			effectiveDate.where(a1, a2);

			Predicate n1 = cb.equal(b.get("effectiveDateStart"), effectiveDate);
			query.where(n1);
			// Get Result
			TypedQuery<Long> result = em.createQuery(query);
			list = result.getResultList();

			data = list.get(0);

		} catch (Exception e) {
			e.printStackTrace();
			log.info(e.getMessage());

		}
		return data;
	}

